160	// 현재 사용자 조회
161	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
162	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
163	  const token = request.headers.authorization.split(" ")[1];
164	  return formatUserResponse(user, token);
165	});
