167	// 사용자 정보 수정
168	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
169	  const body = request.body?.user || {};
170	  const updates: any = {};
171	  if (body.username !== undefined) {
172	    if (body.username === "" || body.username === null) {
173	      reply.code(422).send({ errors: { username: ["can't be blank"] } });
174	      return;
175	    }
176	    updates.username = body.username;
177	  }
178	  if (body.email !== undefined) {
179	    if (body.email === "" || body.email === null) {
180	      reply.code(422).send({ errors: { email: ["can't be blank"] } });
181	      return;
182	    }
183	    updates.email = body.email;
184	  }
185	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
186	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
187	  if (body.password !== undefined) {
188	    if (body.password === "" || body.password === null || body.password.length < 8) {
189	      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
190	      return;
191	    }
192	    updates.password = await bcrypt.hash(body.password, 10);
193	  }
194	
195	  // 고유성 검증
196	  if (updates.username || updates.email) {
197	    const existing = await prisma.user.findFirst({
198	      where: {
199	        id: { not: request.userId },
200	        OR: [
201	          updates.username !== undefined ? { username: updates.username } : undefined,
202	          updates.email !== undefined ? { email: updates.email } : undefined,
203	        ].filter((e: any) => e !== undefined),
204	      },
205	    });
206	    if (existing) {
207	      const err: Record<string, string[]> = {};
208	      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
209	      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
210	      reply.code(422).send({ errors: err });
211	      return;
212	    }
213	  }
214	
215	  const user = await prisma.user.update({
216	    where: { id: request.userId },
217	    data: updates,
218	  });
219	  const token = request.headers.authorization.split(" ")[1];
220	  return formatUserResponse(user, token);
221	});
