227	// 프로필 조회
228	app.get("/api/profiles/:username", async (request: any, reply: any) => {
229	  const username = request.params.username as string;
230	  const profile = await prisma.user.findUnique({
231	    where: { username },
232	    select: { id: true, username: true, bio: true, image: true },
233	  });
234	  if (!profile) {
235	    reply.code(404).send({ errors: { profile: ["not found"] } });
236	    return;
237	  }
238	
239	  // 팔로우 상태 확인 (인증된 경우)
240	  let following = false;
241	  const authHeader = request.headers.authorization;
242	  if (authHeader) {
243	    const parts = authHeader.split(" ");
244	    if (parts[0] === "Token") {
245	      try {
246	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
247	        const follow = await prisma.follow.findUnique({
248	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
249	        });
250	        following = !!follow;
251	      } catch {
252	        following = false;
253	      }
254	    }
255	  }
256	
257	  return { profile: { ...profile, following } };
258	});
