318	// 아티클 생성
319	app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
320	  const { title, description, body, tagList = [] } = request.body?.article || {};
321	  if (!title || !description || !body) {
322	    const errs: Record<string, string[]> = {};
323	    if (!title) errs.title = ["can't be blank"];
324	    if (!description) errs.description = ["can't be blank"];
325	    if (!body) errs.body = ["can't be blank"];
326	    reply.code(422).send({ errors: errs });
327	    return;
328	  }
329	  const slug = generateSlug(title);
330	  const existingArticle = await prisma.article.findUnique({ where: { slug } });
331	  if (existingArticle && existingArticle.authorId === request.userId) {
332	    await prisma.article.update({
333	      where: { id: existingArticle.id },
334	      data: { title, description, body },
335	    });
336	    const updated = await prisma.article.findUnique({
337	      where: { id: existingArticle.id },
338	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
339	    });
340	    reply.code(201).send({
341	      article: formatArticleResponse(updated, false, updated.favorites.length),
342	    });
343	    return;
344	  }
345	  const article = await prisma.article.create({
346	    data: {
347	      slug,
348	      title,
349	      description,
350	      body,
351	      author: { connect: { id: request.userId } },
352	      tags: {
353	        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
354	      },
355	    },
356	    include: {
357	      author: { select: { username: true, bio: true, image: true } },
358	      tags: true,
359	      favorites: true,
360	    },
361	  });
362	  reply.code(201).send({
363	    article: formatArticleResponse(article, false, article.favorites.length),
364	  });
365	  return;
366	});
