368	// 아티클 목록 조회
369	app.get("/api/articles", async (request: any, reply: any) => {
370	  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
371	  const lim = parseInt(limit as string, 10);
372	  const off = parseInt(offset as string, 10);
373	
374	  const where: any = {};
375	  if (author) {
376	    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
377	    if (!user) {
378	      return { articles: [], articlesCount: 0 };
379	    }
380	    where.authorId = user.id;
381	  }
382	  if (tag) {
383	    where.tags = { some: { tag: (tag as string).toLowerCase() } };
384	  }
385	
386	  if (favorited) {
387	    const user = await prisma.user.findUnique({
388	      where: { username: favorited as string },
389	      select: { id: true },
390	    });
391	    if (!user) {
392	      return { articles: [], articlesCount: 0 };
393	    }
394	    const favorites = await prisma.favorite.findMany({
395	      where: { userId: user.id },
396	      select: { articleId: true },
397	    });
398	    const articleIds = favorites.map((f: any) => f.articleId);
399	    if (articleIds.length === 0) {
400	      return { articles: [], articlesCount: 0 };
401	    }
402	    const articles = await prisma.article.findMany({
403	      where: { id: { in: articleIds } },
404	      take: lim,
405	      skip: off,
406	      orderBy: { createdAt: "desc" },
407	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
408	    });
409	    return {
410	      articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
411	      articlesCount: articles.length,
412	    };
413	  }
414	
415	  const articles = await prisma.article.findMany({
416	    where,
417	    take: lim,
418	    skip: off,
419	    orderBy: { createdAt: "desc" },
420	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
421	  });
422	  const articlesCount = await prisma.article.count({ where });
423	  return {
424	    articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
425	    articlesCount,
426	  };
427	});
