542	app.get("/api/articles/feed", { preHandler: authMiddleware }, async (request: any, reply: any) => {
543	  const { limit = "20", offset = "0" } = request.query || {};
544	  const lim = parseInt(limit as string, 10);
545	  const off = parseInt(offset as string, 10);
546	
547	  const follows = await prisma.follow.findMany({
548	    where: { followerId: request.userId },
549	    select: { followingId: true },
550	  });
551	  const followingIds = follows.map((f: any) => f.followingId);
552	
553	  let articles: any[];
554	  let articlesCount: number;
555	
556	  if (followingIds.length === 0) {
557	    articles = [];
558	    articlesCount = 0;
559	  } else {
560	    articles = await prisma.article.findMany({
561	      where: { authorId: { in: followingIds } },
562	      take: lim,
563	      skip: off,
564	      orderBy: { createdAt: "desc" },
565	      include: {
566	        author: { select: { id: true, username: true, bio: true, image: true } },
567	        tags: true,
568	        favorites: true,
569	      },
570	    });
571	    articlesCount = await prisma.article.count({
572	      where: { authorId: { in: followingIds } },
573	    });
574	  }
575	
576	  const enriched = await Promise.all(
577	    articles.map(async (a: any) => {
578	      const author = a.author as { id: number; username: string; bio: string | null; image: string | null };
579	      const isFollowing = await prisma.follow.findUnique({
580	        where: { followerId_followingId: { followerId: request.userId, followingId: author.id } },
581	        select: { id: true },
582	      });
