import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";

const prisma = new PrismaClient();

async function main() {
  console.log("DB 초기화: 모든 데이터 삭제 중...");

  // 외래 키 제약조건 때문에 순서 주의: 종속 테이블부터 삭제
  await prisma.comment.deleteMany();
  await prisma.favorite.deleteMany();
  await prisma.follow.deleteMany();
  // ArticleTag는 복합키라 deleteMany 조심 — 개별 삭제로 우회
  await prisma.$executeRaw`DELETE FROM "ArticleTag"`;
  await prisma.article.deleteMany();
  await prisma.user.deleteMany();

  console.log("DB 초기화 완료");

  // 테스트용 기본 유저 생성 (모든 Hurl 테스트 파일에서 사용)
  const passwordHash = await bcrypt.hash("password123", 10);
  const user = await prisma.user.create({
    data: {
      username: process.env.TEST_UID || "testuid12345",
      email: "test@example.com",
      password: passwordHash,
      bio: null,
      image: null,
    },
  });

  const token = process.env.TEST_TOKEN || "dummy";
  console.log(`테스트 유저 생성 완료: ${user.username} (id: ${user.id})`);
  console.log(`테스트 토큰: ${token}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

