// 아티클 수정
app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({ errors: { article: ["not found"] } });
    return;
  }
  if (article.authorId !== request.userId) {
    reply.code(403).send({ errors: { article: ["forbidden"] } });
    return;
  }

  const body = request.body?.article || {};
  const updates: any = {};
  if (body.title !== undefined) updates.title = body.title;
  if (body.description !== undefined) updates.description = body.description;
  if (body.body !== undefined) updates.body = body.body;

  // 태그 업데이트
  if (body.tagList !== undefined) {
    if (body.tagList === null) {
      reply.code(422).send({ errors: { article: ["tagList can't be blank"] } });
      return;
    }
    if (Array.isArray(body.tagList)) {
      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
      if (body.tagList.length > 0) {
        await prisma.articleTag.createMany({
          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
        });
      }
    }
  }

  // 슬러그 업데이트
  if (updates.title) {
    updates.slug = generateSlug(updates.title);
  }

  const updated = await prisma.article.update({
    where: { id: article.id },
    data: updates,
    include: {
      author: { select: { id: true, username: true, bio: true, image: true } },
      tags: true,
      favorites: true,
    },
  });

