1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터 (상세/즐겨찾기 — body 포함)
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
39	  const { tags: _tags, ...rest } = article;
40	  return {
41	    ...rest,
42	    tagList: tags,
43	    favorited,
44	    favoritesCount,
45	  };
46	}
47	
48	// 아티클 응답 포맷터 (목록/피드 — body 제외)
49	function formatArticleListResponse(article: any, favorited: boolean, favoritesCount: number, authorFollowing?: boolean) {
50	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
51	  const { body, tags: _tags, ...rest } = article;
52	  return {
53	    ...rest,
54	    tagList: tags,
55	    favorited,
56	    favoritesCount,
57	    author: authorFollowing !== undefined ? { ...rest.author, following: authorFollowing } : rest.author,
58	  };
59	}
60	
61	// 인증 미들웨어
62	async function authMiddleware(request: any, reply: any) {
63	  const authHeader = request.headers.authorization;
64	  if (!authHeader) {
65	    reply.code(401).send({ errors: { token: ["is missing"] } });
66	    return;
67	  }
68	  const parts = authHeader.split(" ");
69	  if (parts[0] !== "Token") {
70	    reply.code(401).send({ errors: { token: ["is invalid"] } });
71	    return;
72	  }
73	  try {
74	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
75	    request.userId = decoded.id;
76	  } catch {
77	    reply.code(401).send({ errors: { token: ["is invalid"] } });
78	    return;
79	  }
80	}
81	
82	// 슬러그 생성 헬퍼
83	function generateSlug(title: string): string {
84	  return title.toLowerCase().replace(/\s+/g, "-");
85	}
86	
87	// ──────────────────────────────────────────────────────────────
88	// Fastify 앱 초기화
89	// ──────────────────────────────────────────────────────────────
90	
91	const app = Fastify({
92	  logger: true,
93	});
94	
95	// CORS 수동 설정
96	app.addHook("onRequest", async (request: any, reply: any) => {
97	  reply.header("Access-Control-Allow-Origin", "*");
98	  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
99	  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
100	  if (request.method === "OPTIONS") {
101	    reply.code(204).send();
102	    return;
103	  }
104	});
105	
106	// ──────────────────────────────────────────────────────────────
107	// 사용자 API
108	// ──────────────────────────────────────────────────────────────
109	
110	// 회원가입
111	app.post("/api/users", async (request: any, reply: any) => {
112	  const { username, email, password } = request.body?.user || {};
113	  if (!username || !email || !password) {
114	    const errs: Record<string, string[]> = {};
115	    if (!username) errs.username = ["can't be blank"];
116	    if (!email) errs.email = ["can't be blank"];
117	    if (!password) errs.password = ["can't be blank"];
118	    reply.code(422).send({ errors: errs });
119	    return;
120	  }
121	  const existing = await prisma.user.findFirst({
122	    where: { OR: [{ username }, { email }] },
123	  });
124	  if (existing) {
125	    const err: Record<string, string[]> = {};
126	    if (existing.username === username) err.username = ["has already been taken"];
127	    if (existing.email === email) err.email = ["has already been taken"];
128	    reply.code(409).send({ errors: err });
129	    return;
130	  }
131	  const hashedPassword = await bcrypt.hash(password, 10);
132	  const user = await prisma.user.create({
133	    data: { username, email, password: hashedPassword },
134	  });
135	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
136	  reply.code(201).send(formatUserResponse(user, token));
137	  return;
138	});
139	
140	// 로그인
141	app.post("/api/users/login", async (request: any, reply: any) => {
142	  const { email, password } = request.body?.user || {};
143	  if (!email || !password) {
144	    const errs: Record<string, string[]> = {};
145	    if (!email) errs.email = ["can't be blank"];
146	    if (!password) errs.password = ["can't be blank"];
147	    reply.code(422).send({ errors: errs });
148	    return;
149	  }
150	  const user = await prisma.user.findUnique({ where: { email: email as string } });
151	  if (!user || !(await bcrypt.compare(password, user.password))) {
152	    reply.code(401).send({ errors: { credentials: ["invalid"] } });
153	    return;
154	  }
155	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
156	  reply.code(200).send(formatUserResponse(user, token));
157	  return;
158	});
159	
160	// 현재 사용자 조회
161	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
162	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
163	  const token = request.headers.authorization.split(" ")[1];
164	  return formatUserResponse(user, token);
165	});
166	
167	// 사용자 정보 수정
168	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
169	  const body = request.body?.user || {};
170	  const updates: any = {};
171	  if (body.username !== undefined) {
172	    if (body.username === "" || body.username === null) {
173	      reply.code(422).send({ errors: { username: ["can't be blank"] } });
174	      return;
175	    }
176	    updates.username = body.username;
177	  }
178	  if (body.email !== undefined) {
179	    if (body.email === "" || body.email === null) {
180	      reply.code(422).send({ errors: { email: ["can't be blank"] } });
181	      return;
182	    }
183	    updates.email = body.email;
184	  }
185	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
186	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
187	  if (body.password !== undefined) {
188	    if (body.password === "" || body.password === null || body.password.length < 8) {
189	      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
190	      return;
191	    }
192	    updates.password = await bcrypt.hash(body.password, 10);
193	  }
194	
195	  // 고유성 검증
196	  if (updates.username || updates.email) {
197	    const existing = await prisma.user.findFirst({
198	      where: {
199	        id: { not: request.userId },
200	        OR: [
201	          updates.username !== undefined ? { username: updates.username } : undefined,
202	          updates.email !== undefined ? { email: updates.email } : undefined,
203	        ].filter((e: any) => e !== undefined),
204	      },
205	    });
206	    if (existing) {
207	      const err: Record<string, string[]> = {};
208	      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
209	      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
210	      reply.code(422).send({ errors: err });
211	      return;
212	    }
213	  }
214	
215	  const user = await prisma.user.update({
216	    where: { id: request.userId },
217	    data: updates,
218	  });
219	  const token = request.headers.authorization.split(" ")[1];
220	  return formatUserResponse(user, token);
221	});
222	
223	// ──────────────────────────────────────────────────────────────
224	// 프로필 API
225	// ──────────────────────────────────────────────────────────────
226	
227	// 프로필 조회
228	app.get("/api/profiles/:username", async (request: any, reply: any) => {
229	  const username = request.params.username as string;
230	  const profile = await prisma.user.findUnique({
231	    where: { username },
232	    select: { id: true, username: true, bio: true, image: true },
233	  });
234	  if (!profile) {
235	    reply.code(404).send({ errors: { profile: ["not found"] } });
236	    return;
237	  }
238	
239	  // 팔로우 상태 확인 (인증된 경우)
240	  let following = false;
241	  const authHeader = request.headers.authorization;
242	  if (authHeader) {
243	    const parts = authHeader.split(" ");
244	    if (parts[0] === "Token") {
245	      try {
246	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
247	        const follow = await prisma.follow.findUnique({
248	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
249	        });
250	        following = !!follow;
251	      } catch {
252	        following = false;
253	      }
254	    }
255	  }
256	
257	  return { profile: { ...profile, following } };
258	});
259	
260	// 팔로우
261	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
262	  const username = request.params.username as string;
263	  const target = await prisma.user.findUnique({
264	    where: { username },
265	    select: { id: true },
266	  });
267	  if (!target) {
268	    reply.code(404).send({ errors: { profile: ["not found"] } });
269	    return;
270	  }
271	  if (target.id === request.userId) {
272	    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
273	    return;
274	  }
275	  await prisma.follow.upsert({
276	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
277	    create: { followerId: request.userId, followingId: target.id },
278	    update: {},
279	  });
280	  const profile = await prisma.user.findUnique({
281	    where: { username },
282	    select: { id: true, username: true, bio: true, image: true },
283	  });
284	  const isFollowing = await prisma.follow.findUnique({
285	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
286	  });
287	  return { profile: { ...profile, following: !!isFollowing } };
288	});
289	
290	// 언팔로우
291	app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
292	  const username = request.params.username as string;
293	  const target = await prisma.user.findUnique({
294	    where: { username },
295	    select: { id: true },
296	  });
297	  if (!target) {
298	    reply.code(404).send({ errors: { profile: ["not found"] } });
299	    return;
300	  }
301	  await prisma.follow.deleteMany({
302	    where: { followerId: request.userId, followingId: target.id },
303	  });
304	  const profile = await prisma.user.findUnique({
305	    where: { username },
306	    select: { id: true, username: true, bio: true, image: true },
307	  });
308	  const isFollowing = await prisma.follow.findUnique({
