import Fastify from "fastify";
import { PrismaClient } from "@prisma/client";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import dotenv from "dotenv";

dotenv.config();

const prisma = new PrismaClient();
const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";

// Fastify 타입 확장
declare module "fastify" {
  interface FastifyRequest {
    userId?: number;
  }
}

// ──────────────────────────────────────────────────────────────
// 유틸리티 함수들
// ──────────────────────────────────────────────────────────────

// 사용자 응답 포맷터
function formatUserResponse(user: any, token: string) {
  return {
    user: {
      username: user.username,
      email: user.email,
      bio: user.bio,
      image: user.image,
      token,
    },
  };
}

// 아티클 응답 포맷터 (상세/즐겨찾기 — body 포함)
function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
  const { tags: _tags, ...rest } = article;
  return {
    ...rest,
    tagList: tags,
    favorited,
    favoritesCount,
  };
}

// 아티클 응답 포맷터 (목록/피드 — body 제외)
function formatArticleListResponse(article: any, favorited: boolean, favoritesCount: number, authorFollowing?: boolean) {
  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
  const { body, tags: _tags, ...rest } = article;
  return {
    ...rest,
    tagList: tags,
    favorited,
    favoritesCount,
    author: authorFollowing !== undefined ? { ...rest.author, following: authorFollowing } : rest.author,
  };
}

// 인증 미들웨어
async function authMiddleware(request: any, reply: any) {
  const authHeader = request.headers.authorization;
  if (!authHeader) {
    reply.code(401).send({ errors: { token: ["is missing"] } });
    return;
  }
  const parts = authHeader.split(" ");
  if (parts[0] !== "Token") {
    reply.code(401).send({ errors: { token: ["is invalid"] } });
    return;
  }
  try {
    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
    request.userId = decoded.id;
  } catch {
    reply.code(401).send({ errors: { token: ["is invalid"] } });
    return;
  }
}

// 슬러그 생성 헬퍼
function generateSlug(title: string): string {
  return title.toLowerCase().replace(/\s+/g, "-");
}

// ──────────────────────────────────────────────────────────────
// Fastify 앱 초기화
// ──────────────────────────────────────────────────────────────

const app = Fastify({
  logger: true,
});

// CORS 수동 설정
app.addHook("onRequest", async (request: any, reply: any) => {
  reply.header("Access-Control-Allow-Origin", "*");
  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
  if (request.method === "OPTIONS") {
    reply.code(204).send();
    return;
  }
});

// ──────────────────────────────────────────────────────────────
// 사용자 API
// ──────────────────────────────────────────────────────────────

// 회원가입
app.post("/api/users", async (request: any, reply: any) => {
  const { username, email, password } = request.body?.user || {};
  if (!username || !email || !password) {
    const errs: Record<string, string[]> = {};
    if (!username) errs.username = ["can't be blank"];
    if (!email) errs.email = ["can't be blank"];
    if (!password) errs.password = ["can't be blank"];
    reply.code(422).send({ errors: errs });
    return;
  }
  const existing = await prisma.user.findFirst({
    where: { OR: [{ username }, { email }] },
  });
  if (existing) {
    const err: Record<string, string[]> = {};
    if (existing.username === username) err.username = ["has already been taken"];
    if (existing.email === email) err.email = ["has already been taken"];
    reply.code(409).send({ errors: err });
    return;
  }
  const hashedPassword = await bcrypt.hash(password, 10);
  const user = await prisma.user.create({
    data: { username, email, password: hashedPassword },
  });
