    where: { id: article.id },
    data: updates,
    include: {
      author: { select: { id: true, username: true, bio: true, image: true } },
      tags: true,
      favorites: true,
    },
  });
  const updatedAuthor = updated.author as { id: number; username: string; bio: string | null; image: string | null };
